#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    int minimumFinishTime(std::vector<int>& tasks, int workers) {
        int low = *std::max_element(tasks.begin(), tasks.end());
        int high = std::accumulate(tasks.begin(), tasks.end(), 0);

        auto canFinish = [&](int limit) {
            int used = 1, cur = 0;
            for (int t : tasks) {
                if (cur + t > limit) {
                    used++;
                    cur = t;
                    if (used > workers) return false;
                } else {
                    cur += t;
                }
            }
            return true;
        };

        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canFinish(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int minimumFinishTime(int[] tasks, int workers) {
        int low = 0, high = 0;
        for (int t : tasks) {
            low = Math.max(low, t);
            high += t;
        }
        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            int used = 1, cur = 0;
            boolean ok = true;
            for (int t : tasks) {
                if (cur + t > mid) {
                    used++;
                    cur = t;
                    if (used > workers) {
                        ok = false;
                        break;
                    }
                } else {
                    cur += t;
                }
            }
            if (ok) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
}

function minimumFinishTime(tasks, workers) {
    let low = Math.max(...tasks);
    let high = tasks.reduce((a, b) => a + b, 0);
    let ans = high;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        let used = 1, cur = 0, ok = true;
        for (const t of tasks) {
            if (cur + t > mid) {
                used++;
                cur = t;
                if (used > workers) {
                    ok = false;
                    break;
                }
            } else {
                cur += t;
            }
        }
        if (ok) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
}
